# Generated by secure-by-design v0.1.0 for DPDP §6 (Consent).
# Reads from ../../privacy-security-manifest.yaml.
# Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
# Docs: docs/scaffolds/consent.md
#
# Reference: India DPDP Act 2023, §5 (Notice), §6 (Consent), §7 (Legitimate use).
# This file scaffolds the *recording*, *verification*, and *withdrawal* of consent.
# It is not a substitute for legal review of your consent flow or notice text.

from __future__ import annotations

import dataclasses
import hashlib
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import Literal, Protocol

from fastapi import HTTPException

# 'explicit' is consent under §6. The rest are §7 legitimate uses; §7 has no general
# "contract" ground, so there is no such value here.
ConsentBasis = Literal['explicit', 'public-interest', 'medical-emergency', 'employment']

ConsentPurpose = str  # e.g. 'patient.diagnosis.ai-suggestion'


def _now() -> datetime:
    return datetime.now(timezone.utc)


@dataclass(frozen=True)
class ConsentRecord:
    data_principal_id: str                         # the user / patient ID
    purpose: ConsentPurpose                        # specific purpose; do not collapse multiple purposes into one
    category: str                                  # matches dataCategories[].name in manifest
    basis: ConsentBasis
    notice_version: str                            # version hash of the notice text shown
    consent_text_hash: str                         # SHA-256 of the exact consent text
    language: str                                  # ISO 639-1 (e.g. 'en', 'hi', 'ta')
    given_by_actor: Literal['self', 'parent-guardian']  # parent-guardian → see children_gate.py
    channel: Literal['web', 'mobile', 'in-person', 'api']
    given_at: datetime = field(default_factory=_now)  # timezone-aware
    withdrawn_at: datetime | None = None
    expires_at: datetime | None = None             # optional, timezone-aware — drives re-prompt


class ConsentStore(Protocol):
    async def insert(self, record: ConsentRecord) -> str: ...  # returns consent ID
    async def find_active(self, data_principal_id: str, purpose: ConsentPurpose) -> ConsentRecord | None: ...
    async def withdraw(self, consent_id: str, when: datetime) -> None: ...
    async def list_for(self, data_principal_id: str) -> list[ConsentRecord]: ...


# Inject a concrete ConsentStore (SQLAlchemy, Tortoise, etc.) at app boot.
_store: ConsentStore | None = None


def set_consent_store(store: ConsentStore) -> None:
    global _store
    _store = store


def _require_store() -> ConsentStore:
    if _store is None:
        raise RuntimeError('secure-by-design: ConsentStore not configured. Call set_consent_store() at app boot.')
    return _store


def hash_consent_text(text: str) -> str:
    return hashlib.sha256(text.encode('utf-8')).hexdigest()


async def record_consent(record: ConsentRecord) -> str:
    """
    Record a consent event. Call when the data principal clicks "I agree" on a notice.

    DPDP §6 points this helps with:
     - Recorded with purpose
     - Recorded with the notice text actually shown (via consent_text_hash)
     - Withdrawable (withdraw_consent() below)

    NOT handled by this function — you must also:
     - Keep consent free, specific, informed, unconditional and unambiguous
     - Present the notice in a clear language (§5(3))
     - Make withdrawal as easy as giving consent (§6(4))
     - Refrain from making consent a precondition for service provision unless the
       service legitimately requires the data (§6(2))
    """
    return await _require_store().insert(dataclasses.replace(record, withdrawn_at=None))


async def verify_consent(data_principal_id: str, purpose: ConsentPurpose) -> ConsentRecord | None:
    """
    Check whether the data principal has active consent for a specific purpose.
    Use this gate BEFORE any code path that processes personal data for that purpose.

    Returns None if no active consent exists. Caller must refuse the operation
    or fall back to a legitimate-use basis under §7 (if applicable).
    """
    record = await _require_store().find_active(data_principal_id, purpose)
    if record is None:
        return None
    if record.withdrawn_at is not None:
        return None
    if record.expires_at is not None and record.expires_at < _now():
        return None
    return record


async def withdraw_consent(consent_id: str) -> None:
    """
    Withdraw consent. After this, any subsequent verify_consent() returns None.
    Per §6(5), withdrawal must not affect lawfulness of processing done before withdrawal.
    """
    await _require_store().withdraw(consent_id, _now())


async def list_consents(data_principal_id: str) -> list[ConsentRecord]:
    """Surface a data principal's full consent history. Used by the DSR access endpoint."""
    return await _require_store().list_for(data_principal_id)


class ConsentRequiredError(HTTPException):
    code = 'CONSENT_REQUIRED'

    def __init__(self, purpose: ConsentPurpose) -> None:
        # 451 Unavailable For Legal Reasons
        super().__init__(status_code=451, detail=f'No active consent for purpose={purpose}. DPDP §6.')


async def require_consent(data_principal_id: str, purpose: ConsentPurpose) -> ConsentRecord:
    """
    Convenience guard for FastAPI handlers. Raises if no active consent, which FastAPI
    turns into a 451 response.
    """
    record = await verify_consent(data_principal_id, purpose)
    if record is None:
        raise ConsentRequiredError(purpose)
    return record
